#!/usr/bin/env bash
# Smoke-test the Compose stack: start Grafana and VictoriaMetrics, provision a
# dashboard generated by the collector code, and check through Grafana's HTTP
# API that the datasource, the dashboard and a written sample all work.
#
# Usage: scripts/compose-smoke.sh
# Needs docker (with compose), uv, curl, jq and openssl. The collector service
# is not started (it needs Bluetooth). Grafana is published on 127.0.0.1 only,
# on SMOKE_GRAFANA_PORT or a free port. Each run uses its own compose project
# (ruuvi-smoke-<random>), removed with its volumes on exit, so it never touches
# a real deployment. Any .env file is ignored.
set -euo pipefail

repo=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$repo"

project=ruuvi-smoke-$(openssl rand -hex 4)
work=$(mktemp -d)
compose=(docker compose -p "$project" --env-file "$work/empty.env"
  -f docker-compose.yml -f "$work/compose.override.yml")

cleanup() {
  status=$?
  if ((status != 0)); then
    echo "::group::docker compose logs"
    "${compose[@]}" logs --no-color || true
    echo "::endgroup::"
    echo "FAIL: compose smoke test" >&2
  fi
  if ! out=$("${compose[@]}" down -v --remove-orphans 2>&1); then
    echo "$out" >&2
    echo "FAIL: docker compose down failed" >&2
    status=1
  fi
  rm -rf "$work"
  exit "$status"
}
trap cleanup EXIT

mac="AA:BB:CC:DD:EE:01"
value=21.5
# A minute old and queried at that time, so VictoriaMetrics' query latency
# offset never hides it, however long startup takes.
ts=$(($(date +%s) - 60))

# Throwaway admin password, never committed.
export GF_ADMIN_PASSWORD
GF_ADMIN_PASSWORD=$(openssl rand -hex 16)
# Loopback only; an empty port lets Docker pick a free one.
export GRAFANA_PORT="127.0.0.1:${SMOKE_GRAFANA_PORT:-}"

# Mount the generated dashboard instead of ./dashboards, so a real one is
# never overwritten. Compose merges volumes by target path.
cat >"$work/compose.override.yml" <<EOF
services:
  grafana:
    volumes:
      - $work/dashboards:/var/lib/grafana/dashboards:ro
EOF
: >"$work/empty.env"

fail() {
  echo "FAIL: $*" >&2
  exit 1
}

# Generate the dashboard and a sample line with the collector's own code.
mkdir -p "$work/dashboards"
line=$(uv run --quiet --locked --directory collector python - \
  "$work/dashboards/ruuvi.json" "$mac" "$value" "$ts" <<'PY'
import sys

sys.path.insert(0, "src")
from config import TagConfig
from dashboard import write_dashboard
from decoder import RuuviReading
from writer import format_line_protocol

path, mac, value, ts = sys.argv[1], sys.argv[2], float(sys.argv[3]), int(sys.argv[4])
write_dashboard([TagConfig(mac=mac, name="Smoke Test")], path)
reading = RuuviReading(
    mac=mac, temperature=value, humidity=45.0, pressure=1013.0,
    acceleration_x=0.0, acceleration_y=0.0, acceleration_z=1.0,
    battery_voltage=3.0, tx_power=4, movement_counter=1, measurement_sequence=1,
)
print(format_line_protocol(reading, "Smoke Test", ts * 10**9, rssi=-60))
PY
)
# Grafana runs as its own user; mktemp -d makes the dir private.
chmod -R a+rX "$work"

"${compose[@]}" up -d --wait grafana victoriametrics
grafana="http://$("${compose[@]}" port grafana 3000)"

api() {
  curl -sS --fail-with-body --max-time 10 -u "admin:$GF_ADMIN_PASSWORD" "$grafana$1"
}

echo "Waiting for Grafana on $grafana"
for _ in $(seq 60); do
  api /api/health >/dev/null 2>&1 && break
  sleep 2
done
api /api/health >/dev/null || fail "Grafana did not become healthy"

health=$(api /api/datasources/uid/victoriametrics/health) ||
  fail "datasource health check failed: $health"
[[ $(jq -r .status <<<"$health") == OK ]] || fail "datasource unhealthy: $health"
echo "OK: victoriametrics datasource is healthy"

# The provisioner reads the file at startup; allow a little time for it.
for _ in $(seq 15); do
  dash=$(api /api/dashboards/uid/ruuvi-sensors 2>&1) && ok=1 && break
  ok=
  sleep 2
done
[[ -n ${ok:-} ]] || fail "dashboard ruuvi-sensors was not provisioned: $dash"
panels=$(jq '.dashboard.panels | length' <<<"$dash")
((panels > 0)) || fail "dashboard ruuvi-sensors has no panels"
echo "OK: dashboard ruuvi-sensors loads with $panels panels"

"${compose[@]}" exec -T victoriametrics \
  wget -qO- --post-data "$line" http://127.0.0.1:8428/write >/dev/null
query=$(jq -rn --arg q "ruuvi_temperature{mac=\"$mac\"}" '$q | @uri')
got=
for _ in $(seq 15); do
  result=$(api "/api/datasources/proxy/uid/victoriametrics/api/v1/query?query=$query&time=$ts" 2>&1) || true
  got=$(jq -r '.data.result[0].value[1] // empty' <<<"$result" 2>/dev/null) || true
  [[ -n $got ]] && break
  sleep 2
done
[[ $got == "$value" ]] || fail "sample did not come back through Grafana: ${result:-}"
echo "OK: sample ruuvi_temperature=$got came back through the Grafana proxy"

logs=$("${compose[@]}" logs --no-color grafana)
errors=$(grep 'level=error' <<<"$logs" || true)
[[ -z $errors ]] || fail "Grafana logged errors:"$'\n'"$errors"
echo "OK: Grafana logged no errors"
echo "PASS: compose smoke test"
